# [doc = " Type of a struct field or tuple variant field in the syntax tree."] # [derive (Clone , Debug , PartialEq)] # [cfg_attr (feature = "serde" , derive (Serialize , Deserialize) , serde (rename_all = "lowercase"))] pub enum Type { # [doc = " Syntax tree type defined by Syn."] # [doc = ""] # [doc = " This name will match the ident of some `Node`."] Syn (String) , # [doc = " Type defined by the Rust language or standard library."] # [doc = ""] # [doc = " All such types used by Syn are accessible in the Rust prelude and can be"] # [doc = " used without a qualifying path in most Rust code."] Std (String) , # [doc = " Type defined by proc-macro2."] # [doc = ""] # [doc = " The type is accessible in the proc-macro2 public API as"] # [doc = " `proc_macro2::#name`."] # [cfg_attr (feature = "serde" , serde (rename = "proc_macro2"))] Ext (String) , # [doc = " Keyword or punctuation token type defined by Syn."] # [doc = ""] # [doc = " This name will match one of the keys in the `tokens` map."] Token (String) , # [doc = " Grouping token defined by Syn."] # [doc = ""] # [doc = " The type is accessible in the Syn public API as `syn::token::#name`."] Group (String) , # [doc = " Punctuated list."] # [doc = ""] # [doc = " This refers to `syn::punctuated::Punctuated<T, P>` with the specified"] # [doc = " element type and punctuation."] Punctuated (Punctuated) , # [doc = " `std::option::Option`"] Option (Box < Type >) , # [doc = " `std::boxed::Box`"] Box (Box < Type >) , # [doc = " `std::vec::Vec`"] Vec (Box < Type >) , # [doc = " Rust tuple with two or more fields."] Tuple (Vec < Type >) , }